using Wayd.Common.Domain.Enums.Imports;

namespace Wayd.Common.Application.Imports;

/// <summary>
/// Where a person goes to see what an import row did: the record it created, or — for a record with no page
/// of its own, such as a membership or a dependency — the record it belongs to.
/// </summary>
/// <remarks>
/// Looked up when the results are read rather than stored with the row. Most keys are generated by the
/// database on save, after the pass that creates the record has already reported it, and a project's key
/// can be changed afterwards; a stored copy would be missing or stale.
/// </remarks>
/// <param name="Type">The kind of record the link opens.</param>
/// <param name="Key">The key its page is addressed by.</param>
/// <param name="Name">What to call it, so the link reads as more than a number.</param>
/// <param name="ParentKey">The key of the record its page sits under — a planning interval objective's planning interval. Null for any other type.</param>
public sealed record ImportRecordLink(ImportRecordType Type, string Key, string? Name, string? ParentKey = null);
